async function verifyIllusionCleanup(frame){
 return frame.evaluate(async()=>{
  const api=SAIllusionDroidConsole,unit=SACombatBridge.state().units.find(u=>u.id===document.querySelector('dialog[data-sic-id="lure"]')?.dataset.operatorId)||SACombatBridge.state().units.find(u=>u.location?.starshipId==='debug-ship'),doc=parent.document.querySelector('dialog[data-sic-id="lure"]')?parent.document:document;
  const settle=async predicate=>{const end=performance.now()+2500;while(!predicate()){if(performance.now()>end)throw Error('cleanup condition timeout');await new Promise(r=>setTimeout(r,20));}};
  SAShipNavigationUI.remember(unit);doc.querySelector('dialog[data-sic-id="lure"]')?.close();await settle(()=>!api.isOpen());
  const originalSet=window.setInterval,originalClear=window.clearInterval,originalMount=SAConsoleCommon.mount,originalAlert=doc.defaultView.alert,live=new Map(),history=[];
  window.setInterval=function(fn,ms,...args){const stack=new Error().stack,id=originalSet.call(this,fn,ms,...args);if(/console-common|illusion-droid-console|ship-navigation-ui/.test(stack)){live.set(id,{ms,stack});history.push(ms);}return id;};
  window.clearInterval=function(id){live.delete(id);return originalClear.call(this,id);};
  const expect=(ok,message)=>{if(!ok)throw Error(message);};
  const open=async()=>{await api.open(unit,'lure');expect(api.isOpen(),'owner present');expect(doc.querySelectorAll('dialog[data-sic-id="lure"][open]').length===1,'exactly one dialog');expect([...live.values()].filter(x=>x.ms===250).length===1,'one real common timer');};
  const results=[];
  try{
   for(const mode of ['pagehide','abrupt-close','failed-mount','reopen']){
    if(mode==='failed-mount'){SAConsoleCommon.mount=function(...args){originalMount.apply(this,args);throw Error('owned test mount failure after real shared mount');};doc.defaultView.alert=()=>{};await api.open(unit,'lure');SAConsoleCommon.mount=originalMount;doc.defaultView.alert=originalAlert;}
    else{await open();const old=doc.querySelector('dialog[data-sic-id="lure"][open]');if(mode==='pagehide')window.dispatchEvent(new PageTransitionEvent('pagehide',{persisted:true}));else{old.close();old.remove();}}
    await settle(()=>!api.isOpen()&&live.size===0);expect(!doc.querySelector('dialog[data-sic-id="lure"][open]'),'no orphan dialog');results.push({mode,remainingTimers:live.size,owner:api.isOpen()});
   }
   expect(history.includes(250)&&history.includes(400),'real shared and renderer intervals exercised');return{results,intervals:history};
  }finally{SAConsoleCommon.mount=originalMount;doc.defaultView.alert=originalAlert;window.setInterval=originalSet;window.clearInterval=originalClear;}
 });
}

